DECLARE @ID INT declare @tmpDecl table( Action varchar(10), ID int)
Merge cdn.DefPodNag as trg using (values('IFT-2R',8,702,0,'',79262,0,4,0,0,1,0,1,3,1,3,0,'cc6e12eaf55fea79c43447b55949715a',0,'2018.2.1',0,0,'Deklaracja','xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:etd="http://crd.gov.pl/xml/schematy/dziedzinowe/mf/2016/01/25/eD/DefinicjeTypy/" xmlns:tns="http://crd.gov.pl/wzor/2018/07/17/5570/" xmlns:zzu="http://crd.gov.pl/xml/schematy/dziedzinowe/mf/2016/02/05/eD/ORDZU/" xmlns="http://crd.gov.pl/wzor/2018/07/17/5570/" xsi:schemaLocation="http://crd.gov.pl/wzor/2018/07/17/5570/ http://crd.gov.pl/wzor/2018/07/17/5570/schemat.xsd"')) as src (DPN_Symbol,DPN_Wersja,DPN_TypPodatku,DPN_Zalacznik,DPN_Nadrzedna,DPN_DataOd,DPN_DataDo,DPN_IloscStron,DPN_Platnosci,DPN_Ksiegowanie,DPN_NrPozIloscPodpoziomow,DPN_ZalacznikOkresDef,DPN_PoczatekOkresu,DPN_KoniecOkresu,DPN_PoczatekPodOkresu,DPN_KoniecPodOkresu,DPN_TypDeklaracji,DPN_SumaKontrolna,DPN_WersjaNadrzednej,DPN_WersjaWewn,DPN_TypUrzedu,DPN_Lp,DPN_XMLTagNazwa,DPN_XMLTagAtrybuty) on (trg.DPN_Symbol=src.DPN_Symbol and trg.DPN_Wersja=src.DPN_Wersja) when matched and (trg.DPN_Symbol<>src.DPN_Symbol or trg.DPN_Wersja<>src.DPN_Wersja or trg.DPN_TypPodatku<>src.DPN_TypPodatku or trg.DPN_Zalacznik<>src.DPN_Zalacznik or trg.DPN_Nadrzedna<>src.DPN_Nadrzedna or trg.DPN_DataOd<>src.DPN_DataOd or trg.DPN_DataDo<>src.DPN_DataDo or trg.DPN_IloscStron<>src.DPN_IloscStron or trg.DPN_Platnosci<>src.DPN_Platnosci or trg.DPN_Ksiegowanie<>src.DPN_Ksiegowanie or trg.DPN_NrPozIloscPodpoziomow<>src.DPN_NrPozIloscPodpoziomow or trg.DPN_ZalacznikOkresDef<>src.DPN_ZalacznikOkresDef or trg.DPN_PoczatekOkresu<>src.DPN_PoczatekOkresu or trg.DPN_KoniecOkresu<>src.DPN_KoniecOkresu or trg.DPN_PoczatekPodOkresu<>src.DPN_PoczatekPodOkresu or trg.DPN_KoniecPodOkresu<>src.DPN_KoniecPodOkresu or trg.DPN_TypDeklaracji<>src.DPN_TypDeklaracji or trg.DPN_SumaKontrolna<>src.DPN_SumaKontrolna or trg.DPN_WersjaNadrzednej<>src.DPN_WersjaNadrzednej or trg.DPN_WersjaWewn<>src.DPN_WersjaWewn or trg.DPN_TypUrzedu<>src.DPN_TypUrzedu or trg.DPN_Lp<>src.DPN_Lp or trg.DPN_XMLTagNazwa<>src.DPN_XMLTagNazwa or trg.DPN_XMLTagAtrybuty<>src.DPN_XMLTagAtrybuty) then update set trg.DPN_Symbol=src.DPN_Symbol,trg.DPN_Wersja=src.DPN_Wersja,trg.DPN_TypPodatku=src.DPN_TypPodatku,trg.DPN_Zalacznik=src.DPN_Zalacznik,trg.DPN_Nadrzedna=src.DPN_Nadrzedna,trg.DPN_DataOd=src.DPN_DataOd,trg.DPN_DataDo=src.DPN_DataDo,trg.DPN_IloscStron=src.DPN_IloscStron,trg.DPN_Platnosci=src.DPN_Platnosci,trg.DPN_Ksiegowanie=src.DPN_Ksiegowanie,trg.DPN_NrPozIloscPodpoziomow=src.DPN_NrPozIloscPodpoziomow,trg.DPN_ZalacznikOkresDef=src.DPN_ZalacznikOkresDef,trg.DPN_PoczatekOkresu=src.DPN_PoczatekOkresu,trg.DPN_KoniecOkresu=src.DPN_KoniecOkresu,trg.DPN_PoczatekPodOkresu=src.DPN_PoczatekPodOkresu,trg.DPN_KoniecPodOkresu=src.DPN_KoniecPodOkresu,trg.DPN_TypDeklaracji=src.DPN_TypDeklaracji,trg.DPN_SumaKontrolna=src.DPN_SumaKontrolna,trg.DPN_WersjaNadrzednej=src.DPN_WersjaNadrzednej,trg.DPN_WersjaWewn=src.DPN_WersjaWewn,trg.DPN_TypUrzedu=src.DPN_TypUrzedu,trg.DPN_Lp=src.DPN_Lp,trg.DPN_XMLTagNazwa=src.DPN_XMLTagNazwa,trg.DPN_XMLTagAtrybuty=src.DPN_XMLTagAtrybuty when not matched by target then insert (DPN_Symbol,DPN_Wersja,DPN_TypPodatku,DPN_Zalacznik,DPN_Nadrzedna,DPN_DataOd,DPN_DataDo,DPN_IloscStron,DPN_Platnosci,DPN_Ksiegowanie,DPN_NrPozIloscPodpoziomow,DPN_ZalacznikOkresDef,DPN_PoczatekOkresu,DPN_KoniecOkresu,DPN_PoczatekPodOkresu,DPN_KoniecPodOkresu,DPN_TypDeklaracji,DPN_SumaKontrolna,DPN_WersjaNadrzednej,DPN_WersjaWewn,DPN_TypUrzedu,DPN_Lp,DPN_XMLTagNazwa,DPN_XMLTagAtrybuty) values(src.DPN_Symbol,src.DPN_Wersja,src.DPN_TypPodatku,src.DPN_Zalacznik,src.DPN_Nadrzedna,src.DPN_DataOd,src.DPN_DataDo,src.DPN_IloscStron,src.DPN_Platnosci,src.DPN_Ksiegowanie,src.DPN_NrPozIloscPodpoziomow,src.DPN_ZalacznikOkresDef,src.DPN_PoczatekOkresu,src.DPN_KoniecOkresu,src.DPN_PoczatekPodOkresu,src.DPN_KoniecPodOkresu,src.DPN_TypDeklaracji,src.DPN_SumaKontrolna,src.DPN_WersjaNadrzednej,src.DPN_WersjaWewn,src.DPN_TypUrzedu,src.DPN_Lp,src.DPN_XMLTagNazwa,src.DPN_XMLTagAtrybuty)
select top 1 @ID = ID from @tmpDecl; if isnull(@ID,0)=0 return;
declare @DPEId_Podzial int = 191
select * into #DefPodElem from cdn.DefPodElem where DPE_DPNID = @ID and DPE_Lp < @DPEId_Podzial; delete from cdn.DefPodElemKolumny where DPK_DPNID = @ID; delete from cdn.DefPodElem where DPE_DPNID = @ID and DPE_Lp < @DPEId_Podzial;
