update trg set trg.DPE_Wyrazenie=src.DPE_Wyrazenie,trg.DPE_DFNID=src.DPE_DFNID,trg.DPE_DFNKwotaWmr = src.DPE_DFNKwotaWmr from cdn.DefPodElem trg join #DefPodElem src on trg.DPE_DPNID=src.DPE_DPNID and trg.DPE_ID=src.DPE_ID where (trg.DPE_DPNID = @ID and (src.DPE_Definiowalne<>0 and trg.DPE_Definiowalne <> 0 or src.DPE_Definiowalne=0 and src.DPE_DFNID<>0) and trg.DPE_Lp < @DPEId_Podzial) drop table #DefPodElem --END
